from openpyxl import load_workbook
import sys, re
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']

samples = ['H12','L17','H19','L24','H26','L31','H35','H40','H42','H47','H50','L50']
print('Validation sample formulas:')
errors=[]
for coord in samples:
    v=ws[coord].value
    print(f'{coord}: {v!r}')
    if v is None or v == '':
        errors.append(f'{coord} is empty')

# Validate all target cells are non-empty and structurally expected.
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        coord=ws.cell(r,c).coordinate
        v=ws.cell(r,c).value
        if not v:
            errors.append(f'{coord} lookup empty')
        elif 'Data!' not in v or 'INDEX(' not in v or 'MATCH(' not in v:
            errors.append(f'{coord} lookup formula wrong: {v}')
        elif 'Data!$H$21:$L$38' not in v or 'Data!$D$21:$D$38' not in v or 'Data!$H$4:$L$4' not in v:
            errors.append(f'{coord} lookup ranges wrong: {v}')

for r in range(35,41):
    for c in range(8,13):
        coord=ws.cell(r,c).coordinate
        v=ws.cell(r,c).value
        if not v:
            errors.append(f'{coord} net SLA empty')
        elif not v.startswith('=(') or '*100' not in v:
            errors.append(f'{coord} net SLA formula unexpected: {v}')

expected_stats={42:'MIN(',43:'MAX(',44:'MEDIAN(',45:'AVERAGE(',46:'PERCENTILE.INC(',47:'PERCENTILE.INC('}
for r, func in expected_stats.items():
    for c in range(8,13):
        coord=ws.cell(r,c).coordinate
        v=ws.cell(r,c).value
        if not v:
            errors.append(f'{coord} statistic empty')
        elif func not in v:
            errors.append(f'{coord} statistic wrong: {v}')

for c in range(8,13):
    coord=ws.cell(50,c).coordinate
    v=ws.cell(50,c).value
    if not v:
        errors.append(f'{coord} weighted mean empty')
    elif 'SUMPRODUCT(' not in v or '/SUM(' not in v:
        errors.append(f'{coord} weighted mean wrong: {v}')

if errors:
    print('\nERRORS:')
    for e in errors:
        print('-', e)
    sys.exit(1)
print('\nAll target cells validated: non-empty, lookup formulas use Data! INDEX/MATCH, statistics and weighted mean functions present.')
